/**
 * 터미널 탭 제목에서 지금 하는 일(작업 이름)만 뽑는다.
 *
 * - `claude`: Claude Code 는 `✳ Terminal blind overlay` 처럼 앞에 스피너 글리프를 붙인 제목을 OSC 로 보낸다.
 *   앱 기본 제목(`Claude Code`)이거나 빈 제목이면 작업 이름이 없다(`null`).
 * - `pi`: Pi-Bolt 는 `π - <세션 이름> - <폴더>` 꼴로 제목을 보낸다. 세션 이름에 ` - ` 가 들어갈 수 있으므로
 *   첫 조각(앱)과 마지막 조각(폴더) 사이를 전부 세션 이름으로 본다. 세션 이름이 없으면 `null`.
 *
 * 탭에 보여 줄 이름을 정하는 쪽은 `null` 이면 하네스 이름을 그대로 쓴다.
 */

type TitleHarness = "pi" | "claude";

/** 앞에 붙은 스피너 글리프(✳ · ⠂ · ⠐ …)와 공백을 걷어낸다. */
function stripSpinner(text: string) {
	return text.replace(/^[^\p{L}\p{N}]+/u, "").trim();
}

export function taskTitle(harness: TitleHarness, title: string): string | null {
	const raw = title.trim();
	if (!raw) return null;
	if (harness === "claude") {
		const topic = stripSpinner(raw);
		if (!topic || topic === "Claude Code") return null;
		return topic;
	}
	/* pi: `앱 - 세션 이름 - 폴더`. 앱도 폴더도 없으면 세션 이름만 있는 제목이 아니다. */
	const parts = raw.split(" - ");
	if (parts.length < 3) return null;
	const session = parts.slice(1, -1).join(" - ").trim();
	return session || null;
}

